#include "journal.hpp"
#include "journal_c.h"
#include <memory>
#include <cstring>
struct finite_joint_journal{std::unique_ptr<ynx::social::finite::Journal>held;};
extern "C" int finite_joint_journal_open_bound(int fd,const char*path,size_t path_n,const finite_joint_intent*raw,finite_joint_journal**out){if(!out)return 2;*out=nullptr;try{if(!raw||!path||!path_n||path_n>4096||path[0]!='/'||std::memchr(path,0,path_n)||!raw->body.data||!raw->frame.data||!raw->body.size||raw->body.size>32768||!raw->frame.size||raw->frame.size>49152)return 2;ynx::social::finite::Intent i;std::memcpy(i.source_history.data(),raw->history,32);std::memcpy(i.canonical_role.data(),raw->canonical_role,32);std::memcpy(i.source_resource.data(),raw->source_resource,32);std::memcpy(i.binding_resource.data(),raw->binding_resource,32);i.role=raw->role;i.body.assign(raw->body.data,raw->body.data+raw->body.size);i.frame.assign(raw->frame.data,raw->frame.data+raw->frame.size);auto p=std::make_unique<finite_joint_journal>();p->held=std::make_unique<ynx::social::finite::Journal>(fd,i,std::string(path,path_n));*out=p.release();return 0;}catch(...){return 8;}}
extern "C" int finite_joint_journal_open(int fd,const finite_joint_intent*raw,finite_joint_journal**out){if(!out)return 2;*out=nullptr;try{if(!raw||!raw->body.data||!raw->frame.data||!raw->body.size||raw->body.size>32768||!raw->frame.size||raw->frame.size>49152)return 2;ynx::social::finite::Intent i;std::memcpy(i.source_history.data(),raw->history,32);std::memcpy(i.canonical_role.data(),raw->canonical_role,32);std::memcpy(i.source_resource.data(),raw->source_resource,32);std::memcpy(i.binding_resource.data(),raw->binding_resource,32);i.role=raw->role;i.body.assign(raw->body.data,raw->body.data+raw->body.size);i.frame.assign(raw->frame.data,raw->frame.data+raw->frame.size);auto p=std::make_unique<finite_joint_journal>();p->held=std::make_unique<ynx::social::finite::Journal>(fd,i);*out=p.release();return 0;}catch(...){return 8;}}
extern "C" int finite_joint_journal_enter(finite_joint_journal*p){try{if(!p)return 2;p->held->enter();return 0;}catch(...){return 8;}}
extern "C" int finite_joint_journal_probe(finite_joint_journal*p){try{if(!p)return -2;return p->held->probeEntered()?1:0;}catch(...){return -8;}}
extern "C" int finite_joint_journal_current(finite_joint_journal*p){try{if(!p)return 2;p->held->intentCurrent();return 0;}catch(...){return 8;}}
extern "C" int finite_joint_journal_retain(finite_joint_journal*p,uint32_t stage,const unsigned char*b,size_t n){try{if(!p||!b||!n||n>65536)return 2;ynx::social::finite::Bytes raw(b,b+n);if(stage==1)p->held->retainClassic(raw);else if(stage==2)p->held->retainPair(raw);else return 2;return 0;}catch(...){return 8;}}
extern "C" int finite_joint_journal_terminal(finite_joint_journal*p){try{if(!p)return 2;p->held->terminal();return 0;}catch(...){return 8;}}
extern "C" int finite_joint_journal_query(finite_joint_journal*p,unsigned char*out,size_t cap,size_t*n){if(n)*n=0;if(!p||!out||!n)return 2;ynx::social::finite::Observation observed;int first=0;try{p->held->queryInto(observed);}catch(...){first=8;}const auto&raw=observed.pair.empty()?observed.classic:observed.pair;if(raw.size()>cap)return first?first:3;if(!raw.empty())std::memcpy(out,raw.data(),raw.size());*n=raw.size();return first;}
extern "C" int finite_joint_journal_close(finite_joint_journal**p){if(!p)return 2;if(!*p)return 0;int first=0;bool done=(*p)->held->close(first);if(done){delete *p;*p=nullptr;}return first?first:(done?0:8);}
